260	   * JSONL events to `container` as they arrive, keeping the most-recent
261	   * entry at the top (most-recent-first ordering).
262	   *
263	   * Polling begins immediately (one fetch on call), then repeats every
264	   * 3 seconds.  Only events after the last seen line are prepended.
265	   *
266	   * @param {HTMLElement} container - The element to prepend log entries into.
267	   * @param {string}      slug      - Project slug used for the API call.
268	   * @param {string}      filename  - JSONL log filename.
269	   * @returns {Function} cleanup — call to stop polling and clear the interval.
270	   */
271	  function renderLogPreview(container, slug, filename) {
272	    var afterLine  = 0;
273	    var stopped    = false;
274	    var intervalId = null;
275	
276	    function fetchEntries() {
277	      if (stopped) return;
278	      API.getRunLogEntries(slug, filename, afterLine).then(function (data) {
279	        if (stopped) return;
280	        var entries    = (data && Array.isArray(data.entries)) ? data.entries : [];
281	        var totalLines = (data && typeof data.totalLines === 'number')
282	          ? data.totalLines
283	          : afterLine;
284	
285	        // Iterate in reverse so that within a batch the earliest entry
286	        // ends up at the top after prepending (each insertBefore pushes
287	        // the previous div down, so the last-iterated entry — the oldest
288	        // in the batch — ends up topmost).  Overall result: newest events
289	        // are always visible at the top without scrolling.
290	        for (var i = entries.length - 1; i >= 0; i--) {
291	          var div = document.createElement('div');
292	          div.className = 'log-preview-entry';
293	          div.textContent = formatLogAction(entries[i]);
294	          container.insertBefore(div, container.firstChild);
295	        }
296	
297	        afterLine = totalLines;
298	      }).catch(function () {
299	        // Polling is best-effort — swallow errors silently.
300	      });
301	    }
302	
303	    fetchEntries();
304	    intervalId = setInterval(fetchEntries, 3000);
305	
306	    return function cleanup() {
307	      stopped = true;
308	      if (intervalId !== null) {
309	        clearInterval(intervalId);
310	        intervalId = null;
311	      }

